import { useEffect, useMemo, useRef, useState } from "react";
import "./Assessment.css";
import AlertInfo from "../AlertInfo";
import {
  Alert,
  Box,
  Button,
  Card,
  CardActionArea,
  CardContent,
  Chip,
  IconButton,
  Paper,
  Skeleton,
  TextField,
  Typography,
  useTheme,
} from "@mui/material";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { useHandleGetCategoriesQuery } from "../features/categoryApi";
import { useHandleGetQuestionsByCategoryQuery } from "../features/questionApi";
import {
  useCreateResponseMutation,
  useGetResponseByEmailQuery,
  useUpdateResponseMutation,
} from "../features/responseApi";
import { skipToken } from "@reduxjs/toolkit/query";
import * as Yup from "yup";
import { useFormik } from "formik";
import Pagination from "../Pagination";
import QuestionNavigator from "../components/assessment/QuestionNavigator";
import AssessmentQuestion from "../components/assessment/AssessmentQuestion";

const emailSchema = Yup.object({
  email: Yup.string()
    .email("Please enter a valid email")
    .required("Email is required"),
});

const PAGE_LIMIT = 5;
/** High enough to load all questions for the navigator (same order as paginated). */
const ALL_QUESTIONS_LIMIT = 500;

function categoryQuestionCount(category) {
  if (typeof category?.questionCount === "number")
    return category.questionCount;
  if (Array.isArray(category?.questionIds)) return category.questionIds.length;
  return 0;
}

function isAnswered(value) {
  return (
    value != null &&
    value !== "" &&
    !(Array.isArray(value) && value.length === 0)
  );
}

export default function Assessment() {
  const theme = useTheme();

  const [selectedCategory, setSelectedCategory] = useState(null);
  const [answers, setAnswers] = useState({});
  const [clearedQuestionIds, setClearedQuestionIds] = useState(() => new Set());
  const [createdResponseId, setCreatedResponseId] = useState(null);
  const [page, setPage] = useState(1);
  const [pendingScrollId, setPendingScrollId] = useState(null);
  const [debouncedEmail, setDebouncedEmail] = useState("");
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });

  const previousEmailRef = useRef("");
  const loadedResponseRef = useRef(null);

  const formik = useFormik({
    initialValues: { email: "" },
    validationSchema: emailSchema,
    validateOnChange: true,
    validateOnBlur: true,
    onSubmit: () => {},
  });

  const email = formik.values.email;

  /* ---------- debounce email for API ---------- */
  useEffect(() => {
    const timer = setTimeout(() => {
      const normalized = email.trim().toLowerCase();
      if (normalized && !formik.errors.email) {
        setDebouncedEmail(normalized);
      } else {
        setDebouncedEmail("");
      }
    }, 400);
    return () => clearTimeout(timer);
  }, [email, formik.errors.email]);

  /* ---------- clear local state when email switches identity ---------- */
  useEffect(() => {
    const normalized = email.trim().toLowerCase();
    const previous = previousEmailRef.current;
    if (previous && normalized && previous !== normalized) {
      setAnswers({});
      setClearedQuestionIds(new Set());
      setCreatedResponseId(null);
      loadedResponseRef.current = null;
    }
    previousEmailRef.current = normalized;
  }, [email]);

  /* ---------- categories ---------- */
  const {
    data: categoriesData,
    isLoading: catLoading,
    isError: catError,
    refetch: refetchCategories,
  } = useHandleGetCategoriesQuery();

  const categories = useMemo(
    () => categoriesData?.data || [],
    [categoriesData],
  );

  /* ---------- paginated questions (currentData = no stale category) ---------- */
  const {
    currentData: pageData,
    isError: isQuestionsError,
    isFetching,
    isLoading: questionsLoading,
    refetch,
  } = useHandleGetQuestionsByCategoryQuery(
    selectedCategory
      ? {
          page,
          limit: PAGE_LIMIT,
          categoryId: selectedCategory._id,
        }
      : skipToken,
  );

  const questions = pageData?.data?.questions ?? [];
  const hasMore = Boolean(pageData?.data?.hasMore);
  const totalPages = pageData?.data?.totalPages ?? 1;

  /* ---------- all questions for navigator ---------- */
  const { currentData: allData } = useHandleGetQuestionsByCategoryQuery(
    selectedCategory
      ? {
          page: 1,
          limit: ALL_QUESTIONS_LIMIT,
          categoryId: selectedCategory._id,
        }
      : skipToken,
  );

  const allCategoryQuestions = allData?.data?.questions ?? [];
  const totalQuestionsInCategory =
    pageData?.data?.totalQuestions ??
    allData?.data?.totalQuestions ??
    (selectedCategory ? categoryQuestionCount(selectedCategory) : 0);

  /* ---------- existing response (currentData) ---------- */
  const { currentData: existingResponse } = useGetResponseByEmailQuery(
    debouncedEmail || skipToken,
  );

  const existingResponseId = existingResponse?.data?._id ?? createdResponseId;

  const [createResponse, { isLoading: creating }] = useCreateResponseMutation();
  const [updateResponse, { isLoading: updating }] = useUpdateResponseMutation();
  const loadingSubmit = creating || updating;

  /* ---------- merge saved answers; local wins ---------- */
  useEffect(() => {
    if (!existingResponse?.data) return;

    const responseId = existingResponse.data._id;
    if (loadedResponseRef.current === responseId) return;
    loadedResponseRef.current = responseId;

    const saved = existingResponse.data.answers || [];
    const savedAnswers = {};
    saved.forEach((answer) => {
      if (answer?.questionId != null && answer.value != null) {
        savedAnswers[String(answer.questionId)] = answer.value;
      }
    });

    setAnswers((previous) => ({
      ...savedAnswers,
      ...previous,
    }));

    setClearedQuestionIds((previous) => {
      const next = new Set(previous);
      saved.forEach((answer) => {
        if (answer?.questionId != null && answer.value != null) {
          next.delete(String(answer.questionId));
        }
      });
      return next;
    });
  }, [existingResponse]);

  useEffect(() => {
    loadedResponseRef.current = null;
  }, [debouncedEmail]);

  /* ---------- navigation ---------- */
  const selectCategory = (category) => {
    setSelectedCategory(category);
    setPage(1);
    setPendingScrollId(null);
    setClearedQuestionIds(new Set());
  };

  const backToCategories = () => {
    setSelectedCategory(null);
    setPage(1);
    setPendingScrollId(null);
    setClearedQuestionIds(new Set());
  };

  const goToPage = (nextPage) => {
    if (nextPage < 1 || nextPage === page) return;
    setPage(nextPage);
  };

  const goToQuestion = (questionId, questionPage) => {
    if (!questionId || !questionPage) return;
    setPendingScrollId(String(questionId));
    if (questionPage !== page) setPage(questionPage);
  };

  useEffect(() => {
    if (!pendingScrollId) return;
    const element = document.getElementById(`question-${pendingScrollId}`);
    if (!element) return;

    element.scrollIntoView({ behavior: "smooth", block: "center" });
    element.animate(
      [
        { boxShadow: "0 0 0 3px rgba(25, 118, 210, 0.35)" },
        { boxShadow: "0 0 0 0 rgba(25, 118, 210, 0)" },
      ],
      { duration: 1200 },
    );
    setPendingScrollId(null);
  }, [pendingScrollId, questions]);

  /* ---------- answers ---------- */
  const handleChange = (questionId, value, type, checked) => {
    const id = String(questionId);
    setAnswers((previous) => {
      const updated = { ...previous };
      if (type === "checkbox") {
        const current = Array.isArray(updated[id]) ? updated[id] : [];
        const next = checked
          ? [...current, value]
          : current.filter((item) => item !== value);
        if (next.length === 0) delete updated[id];
        else updated[id] = next;
      } else {
        updated[id] = value;
      }
      return updated;
    });
    setClearedQuestionIds((previous) => {
      const next = new Set(previous);
      next.delete(id);
      return next;
    });
  };

  const clearSelected = (questionId) => {
    const id = String(questionId);
    setAnswers((previous) => {
      const next = { ...previous };
      delete next[id];
      return next;
    });
    setClearedQuestionIds((previous) => {
      const next = new Set(previous);
      next.add(id);
      return next;
    });
  };

  const answeredCount = useMemo(
    () => allCategoryQuestions.filter((q) => isAnswered(answers[q._id])).length,
    [allCategoryQuestions, answers],
  );

  /* ---------- submit ---------- */
  const showSuccess = (message) =>
    setSnackbar({ open: true, message, severity: "success" });
  const showError = (message) =>
    setSnackbar({ open: true, message, severity: "error" });
  const closeSnackbar = () =>
    setSnackbar((previous) => ({ ...previous, open: false }));

  const handleSubmit = async (event) => {
    event?.preventDefault?.();

    const normalizedEmail = email.trim().toLowerCase();
    if (!normalizedEmail || formik.errors.email) {
      formik.setFieldTouched("email", true, true);
      showError("Enter a valid email");
      return;
    }
    if (!selectedCategory) {
      showError("Select a category first");
      return;
    }

    const currentPageAnswers = questions
      .map((question) => {
        const id = String(question._id);
        if (clearedQuestionIds.has(id)) {
          return {
            questionId: question._id,
            categoryId: question.categoryId || selectedCategory._id,
            value: null,
          };
        }
        const value = answers[id];
        if (!isAnswered(value)) return null;
        return {
          questionId: question._id,
          categoryId: question.categoryId || selectedCategory._id,
          value,
        };
      })
      .filter(Boolean);

    if (currentPageAnswers.length === 0) {
      showError("Please answer at least one question on this page");
      return;
    }

    try {
      if (existingResponseId) {
        await updateResponse({
          responseId: existingResponseId,
          answers: currentPageAnswers,
          email: normalizedEmail,
        }).unwrap();
        showSuccess("Progress saved");
      } else {
        const response = await createResponse({
          answers: currentPageAnswers,
          email: normalizedEmail,
        }).unwrap();
        if (response?.data?._id) {
          setCreatedResponseId(response.data._id);
        }
        showSuccess("Progress saved");
      }

      setClearedQuestionIds((previous) => {
        const next = new Set(previous);
        questions.forEach((q) => next.delete(String(q._id)));
        return next;
      });

      if (hasMore) {
        goToPage(page + 1);
      } else {
        showSuccess(
          "Category answers saved — pick another category if you want",
        );
      }
    } catch (error) {
      console.error("Failed to save assessment:", error);
      showError(error?.data?.message || "Submission failed");
    }
  };

  const showQuestionSkeleton =
    selectedCategory && (questionsLoading || isFetching) && !pageData;

  /* =========================================================
     CATEGORY SCREEN
  ========================================================= */
  if (!selectedCategory) {
    return (
      <Paper
        className="assessment-container"
        sx={{ maxWidth: 800, mx: "auto", p: 2 }}
      >
        <Typography variant="h5" gutterBottom fontWeight={700}>
          Assessment
        </Typography>
        <Typography color="text.secondary" sx={{ mb: 2 }}>
          Choose a category, then answer its questions. You can do categories in
          any order. Use the same email to continue later.
        </Typography>

        <TextField
          fullWidth
          type="email"
          sx={{
            "& .css-1neokyl-MuiInputBase-root-MuiOutlinedInput-root": {
              height: "45px",
            },
            "& .css-16wblaj-MuiInputBase-input-MuiOutlinedInput-input": {
              height: "45px",
              borderRadius: 1,
            },
            mb: 2,
            maxWidth: 360,
          }}
          name="email"
          label="Email"
          value={formik.values.email}
          onChange={formik.handleChange}
          onBlur={formik.handleBlur}
          error={formik.touched.email && Boolean(formik.errors.email)}
          helperText={formik.touched.email ? formik.errors.email : " "}
        />

        {catError && (
          <Alert
            severity="error"
            sx={{ mb: 2 }}
            action={
              <Button color="inherit" size="small" onClick={refetchCategories}>
                Retry
              </Button>
            }
          >
            Failed to load categories
          </Alert>
        )}

        {catLoading ? (
          <Box sx={{ display: "grid", gap: 1.5 }}>
            {[1, 2, 3, 4].map((item) => (
              <Skeleton key={item} variant="rounded" height={72} />
            ))}
          </Box>
        ) : (
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
              gap: 1.5,
            }}
          >
            {categories.map((category) => {
              const count = categoryQuestionCount(category);
              return (
                <Card
                  key={category._id}
                  sx={{ borderRadius: 2 }}
                  variant="outlined"
                >
                  <CardActionArea onClick={() => selectCategory(category)}>
                    <CardContent>
                      <Typography variant="h6" fontWeight={600}>
                        {category.name}
                      </Typography>
                      <Chip
                        size="small"
                        sx={{ mt: 1 }}
                        label={
                          count === 1 ? "1 question" : `${count} questions`
                        }
                      />
                    </CardContent>
                  </CardActionArea>
                </Card>
              );
            })}
          </Box>
        )}

        {!catLoading && !catError && categories.length === 0 && (
          <Alert severity="info" sx={{ mt: 2 }}>
            No categories yet.
          </Alert>
        )}

        <AlertInfo
          open={snackbar.open}
          message={snackbar.message}
          severity={snackbar.severity}
          onClose={closeSnackbar}
        />
      </Paper>
    );
  }

  /* =========================================================
     QUESTIONS ERROR
  ========================================================= */
  if (isQuestionsError && !pageData && !isFetching) {
    return (
      <Paper
        className="assessment-container"
        sx={{ maxWidth: 800, mx: "auto", p: 2 }}
      >
        <Alert severity="error" sx={{ mb: 2 }}>
          Failed to load questions
        </Alert>
        <Button variant="contained" onClick={() => refetch()}>
          Reload
        </Button>
        <Button sx={{ ml: 1 }} onClick={backToCategories}>
          Back to categories
        </Button>
      </Paper>
    );
  }

  /* =========================================================
     QUESTIONS SCREEN
  ========================================================= */
  return (
    <>
      {allCategoryQuestions.length > 0 && (
        <QuestionNavigator
          questions={allCategoryQuestions}
          answers={answers}
          currentPage={page}
          pageLimit={PAGE_LIMIT}
          onQuestionClick={goToQuestion}
        />
      )}

      <Paper
        className="assessment-container"
        sx={{ maxWidth: 800, mx: "auto", p: 2, mt: { xs: 2, md: 2 } }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 2 }}>
          <IconButton
            onClick={backToCategories}
            aria-label="Back to categories"
          >
            <ArrowBackIcon />
          </IconButton>
          <Box sx={{ flex: 1 }}>
            <Typography variant="h6" fontWeight={700}>
              {selectedCategory.name}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {totalQuestionsInCategory} question
              {totalQuestionsInCategory === 1 ? "" : "s"} in this category
            </Typography>
          </Box>
          <Typography variant="body2" color="text.secondary">
            {answeredCount}/{totalQuestionsInCategory}
          </Typography>
        </Box>

        <TextField
          type="email"
          name="email"
          label="Email"
          value={formik.values.email}
          onChange={formik.handleChange}
          onBlur={formik.handleBlur}
          error={formik.touched.email && Boolean(formik.errors.email)}
          helperText={
            formik.touched.email && formik.errors.email
              ? formik.errors.email
              : "Same email restores saved answers"
          }
          sx={{
            "& .css-1neokyl-MuiInputBase-root-MuiOutlinedInput-root": {
              height: "45px",
            },
            "& .css-16wblaj-MuiInputBase-input-MuiOutlinedInput-input": {
              height: "45px",
              borderRadius: 1,
            },
            mb: 2,
            maxWidth: 360,
          }}
        />

        {showQuestionSkeleton ? (
          <Box sx={{ mt: 2 }}>
            {[1, 2, 3].map((item) => (
              <Skeleton key={item} height={88} sx={{ mb: 1 }} />
            ))}
          </Box>
        ) : questions.length === 0 ? (
          <Alert severity="info">No questions in this category yet.</Alert>
        ) : (
          <form
            className="assessment-form"
            onSubmit={(e) => {
              e.preventDefault();
              handleSubmit(e);
            }}
          >
            {questions.map((question) => (
              <AssessmentQuestion
                key={question._id}
                question={question}
                answer={answers[question._id]}
                onChange={handleChange}
                onClear={clearSelected}
                theme={theme}
              />
            ))}

            {totalPages > 1 && (
              <Pagination
                page={page}
                limit={PAGE_LIMIT}
                totalPages={totalPages}
                hasMore={hasMore}
                handleNextPageButton={() => goToPage(page + 1)}
                handlePrevPageButton={() => goToPage(Math.max(1, page - 1))}
                handlePrevPage={(n) => typeof n === "number" && goToPage(n)}
                handleNextPage={(n) => typeof n === "number" && goToPage(n)}
              />
            )}

            <Box sx={{ mt: 2 }}>
              <Button
                type="submit"
                disabled={loadingSubmit}
                variant="contained"
                color="primary"
              >
                {loadingSubmit
                  ? "Saving…"
                  : hasMore
                    ? "Save and continue"
                    : "Save category answers"}
              </Button>
              <Button type="button" sx={{ ml: 1 }} onClick={backToCategories}>
                Other categories
              </Button>
            </Box>
          </form>
        )}

        <AlertInfo
          open={snackbar.open}
          message={snackbar.message}
          severity={snackbar.severity}
          onClose={closeSnackbar}
        />
      </Paper>
    </>
  );
}
