import {
  Box,
  Checkbox,
  FormControl,
  FormControlLabel,
  FormGroup,
  FormLabel,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
  Tooltip,
} from "@mui/material";
import ClearIcon from "@mui/icons-material/Clear";

function isAnswered(value) {
  return (
    value != null &&
    value !== "" &&
    !(Array.isArray(value) && value.length === 0)
  );
}

export default function AssessmentQuestion({
  question,
  answer,
  onChange,
  onClear,
  theme,
}) {
  const inputId = `q-input-${question._id}`;
  const labelId = `q-label-${question._id}`;
  const value =
    answer ?? (question.type === "checkbox" ? [] : "");
  const hasAnswer = isAnswered(value);

  const renderInput = () => {
    switch (question.type) {
      case "textarea":
        return (
          <TextField
            id={inputId}
            fullWidth
            multiline
            minRows={3}
            value={value}
            onChange={(event) =>
              onChange(question._id, event.target.value, question.type)
            }
            inputProps={{ "aria-labelledby": labelId }}
          />
        );

      case "text":
        return (
          <TextField
            id={inputId}
            fullWidth
            value={value}
            onChange={(event) =>
              onChange(question._id, event.target.value, question.type)
            }
            inputProps={{ "aria-labelledby": labelId }}
          />
        );

      case "radio":
        return (
          <FormControl component="fieldset" variant="standard">
            <RadioGroup
              aria-labelledby={labelId}
              value={value}
              name={`radio-${question._id}`}
            >
              {(question.options || []).map((option, index) => (
                <FormControlLabel
                  key={`${question._id}-radio-${index}`}
                  value={option}
                  control={<Radio />}
                  label={option}
                  onChange={() => onChange(question._id, option, "radio")}
                />
              ))}
            </RadioGroup>
          </FormControl>
        );

      case "checkbox":
        return (
          <FormControl component="fieldset" variant="standard">
            <FormGroup role="group" aria-labelledby={labelId}>
              {(question.options || []).map((option, index) => (
                <FormControlLabel
                  key={`${question._id}-check-${index}`}
                  control={
                    <Checkbox
                      checked={
                        Array.isArray(value) && value.includes(option)
                      }
                      onChange={(event) =>
                        onChange(
                          question._id,
                          option,
                          "checkbox",
                          event.target.checked
                        )
                      }
                    />
                  }
                  label={option}
                />
              ))}
            </FormGroup>
          </FormControl>
        );

      case "dropdown":
        return (
          <select
            id={inputId}
            value={value}
            aria-labelledby={labelId}
            onChange={(event) =>
              onChange(question._id, event.target.value, "dropdown")
            }
            style={{
              width: "100%",
              padding: 10,
              borderRadius: 4,
              border: "1px solid #ccc",
              fontSize: 16,
            }}
          >
            <option value="">Select</option>
            {(question.options || []).map((option, index) => (
              <option key={`${question._id}-opt-${index}`} value={option}>
                {option}
              </option>
            ))}
          </select>
        );

      default:
        return null;
    }
  };

  return (
    <Box
      id={`question-${question._id}`}
      className="assessment-question"
      sx={{
        backgroundColor: theme.palette.background.paper,
        scrollMarginTop: "100px",
      }}
    >
      <FormLabel
        id={labelId}
        htmlFor={
          question.type === "text" ||
          question.type === "textarea" ||
          question.type === "dropdown"
            ? inputId
            : undefined
        }
        sx={{
          display: "block",
          fontWeight: 700,
          mb: 1,
          color: "text.primary",
        }}
      >
        {question.label}
      </FormLabel>

      <Box className="assessment-input-block">{renderInput()}</Box>

      <Box
        sx={{
          display: "flex",
          width: "100%",
          justifyContent: "flex-end",
          minHeight: 40,
        }}
      >
        {hasAnswer && (
          <Tooltip title="Clear answer">
            <IconButton
              onClick={() => onClear(question._id)}
              size="small"
              aria-label={`Clear answer for ${question.label}`}
            >
              <ClearIcon />
            </IconButton>
          </Tooltip>
        )}
      </Box>
    </Box>
  );
}