import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Box,
  Card,
  Collapse,
  Divider,
  IconButton,
  List,
  ListItemButton,
  ListItemIcon,
  Typography,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import CheckIcon from "@mui/icons-material/Check";
import DragIndicatorIcon from "@mui/icons-material/DragIndicator";

export function isAnswered(value) {
  return (
    value !== null &&
    value !== undefined &&
    value !== "" &&
    !(Array.isArray(value) && value.length === 0)
  );
}

const PANEL_WIDTH = 300;
const MARGIN = 10;

function defaultPosition(isSmall) {
  if (typeof window === "undefined") {
    return { x: 20, y: 20 };
  }
  const width = isSmall ? 280 : PANEL_WIDTH;
  return {
    x: Math.max(MARGIN, window.innerWidth - width - 20),
    y: isSmall ? 10 : 20,
  };
}

function clampPosition(x, y, width, height) {
  if (typeof window === "undefined") return { x, y };
  const maxX = Math.max(MARGIN, window.innerWidth - width - MARGIN);
  const maxY = Math.max(MARGIN, window.innerHeight - Math.min(height, 80) - MARGIN);
  return {
    x: Math.min(Math.max(MARGIN, x), maxX),
    y: Math.min(Math.max(MARGIN, y), maxY),
  };
}

export default function QuestionNavigator({
  questions = [],
  answers = {},
  currentPage = 1,
  pageLimit = 5,
  onQuestionClick,
}) {
  const theme = useTheme();
  const isSmallScreen = useMediaQuery(theme.breakpoints.down("md"));
  const [open, setOpen] = useState(!isSmallScreen);
  const [position, setPosition] = useState(() => defaultPosition(false));
  const [dragging, setDragging] = useState(false);

  const dragRef = useRef({
    active: false,
    moved: false,
    startX: 0,
    startY: 0,
    originX: 0,
    originY: 0,
  });
  const cardRef = useRef(null);

  useEffect(() => {
    if (isSmallScreen) setOpen(false);
  }, [isSmallScreen]);

  // Re-clamp when window resizes
  useEffect(() => {
    const onResize = () => {
      const rect = cardRef.current?.getBoundingClientRect();
      const w = rect?.width ?? (isSmallScreen ? 280 : PANEL_WIDTH);
      const h = rect?.height ?? 80;
      setPosition((prev) => clampPosition(prev.x, prev.y, w, h));
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [isSmallScreen]);

  const answeredCount = useMemo(
    () => questions.filter((q) => isAnswered(answers[q._id])).length,
    [questions, answers]
  );

  const percentage =
    questions.length > 0
      ? Math.round((answeredCount / questions.length) * 100)
      : 0;

  const endDrag = useCallback(() => {
    const d = dragRef.current;
    if (!d.active) return;
    d.active = false;
    setDragging(false);
  }, []);

  useEffect(() => {
    const onMove = (event) => {
      const d = dragRef.current;
      if (!d.active) return;

      const clientX = event.touches ? event.touches[0].clientX : event.clientX;
      const clientY = event.touches ? event.touches[0].clientY : event.clientY;
      const dx = clientX - d.startX;
      const dy = clientY - d.startY;

      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
        d.moved = true;
      }

      const rect = cardRef.current?.getBoundingClientRect();
      const w = rect?.width ?? PANEL_WIDTH;
      const h = rect?.height ?? 80;
      setPosition(clampPosition(d.originX + dx, d.originY + dy, w, h));

      if (event.cancelable) event.preventDefault();
    };

    const onUp = () => endDrag();

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onUp);

    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onUp);
    };
  }, [endDrag]);

  const startDrag = (event) => {
    // Only primary button / touch
    if (event.type === "pointerdown" && event.button !== 0) return;

    const clientX = event.touches ? event.touches[0].clientX : event.clientX;
    const clientY = event.touches ? event.touches[0].clientY : event.clientY;

    dragRef.current = {
      active: true,
      moved: false,
      startX: clientX,
      startY: clientY,
      originX: position.x,
      originY: position.y,
    };
    setDragging(true);

    if (event.currentTarget.setPointerCapture && event.pointerId != null) {
      try {
        event.currentTarget.setPointerCapture(event.pointerId);
      } catch {
        /* ignore */
      }
    }
  };

  const handleHeaderClick = () => {
    // Don't toggle collapse if the user just dragged
    if (dragRef.current.moved) {
      dragRef.current.moved = false;
      return;
    }
    setOpen((prev) => !prev);
  };

  return (
    <Card
      ref={cardRef}
      elevation={dragging ? 12 : 5}
      sx={{
        position: "fixed",
        left: position.x,
        top: position.y,
        width: { xs: 280, sm: PANEL_WIDTH },
        maxWidth: "calc(100vw - 20px)",
        maxHeight: { xs: "70vh", md: "75vh" },
        zIndex: theme.zIndex.drawer + 1,
        borderRadius: 2,
        overflow: "hidden",
        transition: dragging ? "none" : "box-shadow 0.15s ease",
        userSelect: dragging ? "none" : "auto",
      }}
    >
      <Box
        onPointerDown={startDrag}
        onClick={handleHeaderClick}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            setOpen((prev) => !prev);
          }
        }}
        role="button"
        tabIndex={0}
        aria-expanded={open}
        aria-label="Question navigator. Drag to move, click to expand or collapse."
        sx={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          px: 1,
          py: 1.25,
          cursor: dragging ? "grabbing" : "grab",
          userSelect: "none",
          touchAction: "none",
          "&:hover": { bgcolor: "action.hover" },
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, minWidth: 0 }}>
          <DragIndicatorIcon
            fontSize="small"
            sx={{ color: "text.disabled", flexShrink: 0 }}
            aria-hidden
          />
          <Box sx={{ minWidth: 0 }}>
            <Typography variant="subtitle1" fontWeight={700} noWrap>
              Questions
            </Typography>
            <Typography variant="caption" color="text.secondary" noWrap>
              {answeredCount} of {questions.length} answered
            </Typography>
          </Box>
        </Box>
        <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, flexShrink: 0 }}>
          <Typography variant="caption" color="primary" fontWeight={700}>
            {percentage}%
          </Typography>
          <IconButton size="small" tabIndex={-1} aria-hidden sx={{ pointerEvents: "none" }}>
            <ExpandMoreIcon
              sx={{
                transform: open ? "rotate(180deg)" : "rotate(0deg)",
                transition: "transform 0.2s ease",
              }}
            />
          </IconButton>
        </Box>
      </Box>

      <Collapse in={open}>
        <Divider />
        <List
          disablePadding
          sx={{
            maxHeight: { xs: "60vh", md: "65vh" },
            overflowY: "auto",
          }}
        >
          {questions.length === 0 ? (
            <Box sx={{ p: 2 }}>
              <Typography variant="body2" color="text.secondary">
                No questions available.
              </Typography>
            </Box>
          ) : (
            questions.map((question, index) => {
              const answered = isAnswered(answers[question._id]);
              const questionPage = Math.floor(index / pageLimit) + 1;
              const isCurrentPage = questionPage === currentPage;

              return (
                <ListItemButton
                  key={question._id}
                  onClick={() => onQuestionClick(question._id, questionPage)}
                  selected={isCurrentPage}
                  aria-label={`Question ${index + 1}${
                    answered ? ", answered" : ""
                  }, page ${questionPage}`}
                  sx={{
                    py: 0.5,
                    px: 1,
                    borderLeft: "3px solid",
                    borderColor: isCurrentPage ? "primary.main" : "transparent",
                  }}
                >
                  <ListItemIcon sx={{ minWidth: 36 }}>
                    {answered ? (
                      <Box
                        sx={{
                          width: 18,
                          height: 18,
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          bgcolor: "success.main",
                          color: "white",
                          borderRadius: 0.5,
                        }}
                        aria-hidden
                      >
                        <CheckIcon sx={{ fontSize: 15 }} />
                      </Box>
                    ) : (
                      <Box
                        sx={{
                          width: 18,
                          height: 18,
                          border: "1px solid",
                          borderColor: "text.disabled",
                          borderRadius: 0.5,
                        }}
                        aria-hidden
                      />
                    )}
                  </ListItemIcon>
                  <Typography
                    variant="body2"
                    sx={{
                      flex: 1,
                      minWidth: 0,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                    title={question.label}
                  >
                    {index + 1}. {question.label}
                  </Typography>
                  {isCurrentPage && (
                    <Typography
                      variant="caption"
                      color="primary"
                      fontWeight={600}
                      sx={{ ml: 1, flexShrink: 0 }}
                    >
                      p{questionPage}
                    </Typography>
                  )}
                </ListItemButton>
              );
            })
          )}
        </List>
      </Collapse>
    </Card>
  );
}